import{_ as p,a0 as l,w as i,s as r,ao as t,I as e,x as a,a1 as n,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"怎样在 Android 上手动备份你的短信/彩信？ | LCTT x X-CMD","titleTemplate":false,"description":"怎样在 Android 上手动备份你的短信/彩信？ | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在 Android 上手动备份你的短信/彩信？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在 Android 上手动备份你的短信/彩信？ | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20161017 How To Manually Backup Your SMS MMS Messages On Android","title":"怎样在 Android 上手动备份你的短信/彩信？","tag":"201612","desc":""},"relativePath":"201612/20161017 How To Manually Backup Your SMS MMS Messages On Android.md","filePath":"[post].md"}'),m={name:"201612/20161017 How To Manually Backup Your SMS MMS Messages On Android.md"};function u(T,s,b,f,g,S){const o=l("Link");return i(),r("div",null,[s[17]||(s[17]=t('<h1 id="怎样在-android-上手动备份你的短信-彩信" tabindex="-1">怎样在 Android 上手动备份你的短信/彩信？ <a class="header-anchor" href="#怎样在-android-上手动备份你的短信-彩信" aria-label="Permalink to “怎样在 Android 上手动备份你的短信/彩信？”">​</a></h1><p><img src="https://iwf1.com/wordpress/wp-content/uploads/2016/10/Android-backup-sms-mms.jpg" alt="Android backup sms"></p><p>如果你要换一部手机或升级你的系统，备份你的数据就变得至关重要。我们存储重要数据的位置之一就是我们的短信/彩信，不管是感情价值还是实用价值，备份它们是很有用的。</p><p>然而，不像照片、视频或音频文件可以相对容易地传输和备份，备份短信/彩信比较复杂，通常需要使用第三方 app 或服务。</p><h3 id="为什么要手动备份" tabindex="-1">为什么要手动备份 <a class="header-anchor" href="#为什么要手动备份" aria-label="Permalink to “为什么要手动备份”">​</a></h3><p>尽管现在有很多不同的 app 能够帮你备份短信/彩信，你可能因为以下原因，考虑自己动手备份它们：</p><ol><li>app <strong>可能不能</strong>在所有的设备和安卓版本上都工作。</li><li>app 可能把你的备份数据上传到云端， 有<strong>破坏你的内容安全</strong>的风险。</li><li>通过手动备份，你可以完全掌握你的数据通过哪里，走向哪里，备份过程中减少被间谍软件窥视的危险。</li><li>手动备份相比其他方法<strong>更省时，更省力，更直接</strong>。</li></ol><h3 id="怎么手动备份短信-彩信" tabindex="-1">怎么手动备份短信/彩信？ <a class="header-anchor" href="#怎么手动备份短信-彩信" aria-label="Permalink to “怎么手动备份短信/彩信？”">​</a></h3>',8)),e("p",null,[s[1]||(s[1]=a("要手动备份你的短信/彩信，你需要在你的电脑上安装一个叫做  ",-1)),n(o,{href:"http://developer.android.com/tools/help/adb.html"},{default:d(()=>[...s[0]||(s[0]=[a("adb",-1)])]),_:1}),s[2]||(s[2]=a(" 的安卓工具。",-1))]),s[18]||(s[18]=t(`<p>现在，需要重点知道的是，安卓把短信/彩信通常存储在一个叫做 <code>mmssms.db</code> 的数据库里。</p><p>因为在不同设备上这个数据库的位置可能不相同，而且，其他短信 app 会创建它们自己的数据库，比如 GO SMS 会创建 <code>gommssms.db</code> 数据库， 所以你需要做的第一件事是搜索这些数据库。</p><p>打开命令行工具（我使用了 Linux Terminal， 你也可以使用 Windows CMD 或 PowerShell ）并运行以下命令：</p><p>注意： 以下是完成该任务的一系列命令，再后面是每个命令用途的解释。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb root</span></span>
<span class="line"><span>adb shell</span></span>
<span class="line"><span>find / -name &quot;*mmssms*&quot;</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>adb pull /PATH/TO/mmssms.db /PATH/TO/DESTINATION/FOLDER</span></span></code></pre></div><h4 id="解释" tabindex="-1">解释 <a class="header-anchor" href="#解释" aria-label="Permalink to “解释”">​</a></h4><p>一开始我们使用 <code>adb root</code> 命令来以 root 模式启动 adb － 这样我们就有了读取系统保护文件的权限。</p><p><code>adb shell</code> 用来进入设备的 shell。</p><p>然后， <code>find</code> 命令用来搜索数据库。（在我的例子中，我发现数据库在 <code>/data/data/com.android.providers.telephony/databases/mmssms.db</code>)</p><p>建议：如果你的终端输出了太多无关的结果，可以试试使用 <code>find</code> 的参数来精简结果。(具体参数可以搜索引擎查下)</p>`,10)),e("p",null,[n(o,{href:"http://iwf1.com/wordpress/wp-content/uploads/2016/10/Android-SMSMMS-databases.jpg"},{default:d(()=>[...s[3]||(s[3]=[e("img",{src:"http://iwf1.com/wordpress/wp-content/uploads/2016/10/Android-SMSMMS-databases-730x726.jpg",alt:"Android SMS&MMS databases"},null,-1)])]),_:1})]),s[19]||(s[19]=t("<p><em>安卓短信/彩信数据库</em></p><p>然后我们使用 <code>exit</code> 命令回退到我们的本地系统目录。</p><p>最后，使用 <code>adb pull</code> 把数据库文件复制到我们电脑的一个文件夹里。</p><p>现在，当你想要还原短信/彩信时，不管是还原到新的设备还是新的系统版本， 只要再次搜索新系统中短信/彩信的具体位置，并用我们备份的数据库替换它即可。</p><p>使用 <code>adb push</code> 来替换它，例如：<code>adb push ~/Downloads/mmssms.db /data/data/com.android.providers.telephony/databases/mmssms.db</code></p><hr>",6)),e("p",null,[s[5]||(s[5]=a("via: ",-1)),n(o,{href:"https://iwf1.com/how-to-manually-backup-your-sms-mms-messages-on-android/"},{default:d(()=>[...s[4]||(s[4]=[a("https://iwf1.com/how-to-manually-backup-your-sms-mms-messages-on-android/",-1)])]),_:1})]),e("p",null,[s[9]||(s[9]=a("作者：",-1)),n(o,{href:"https://iwf1.com/tag/android"},{default:d(()=>[...s[6]||(s[6]=[a("Liron",-1)])]),_:1}),s[10]||(s[10]=a(" 译者：",-1)),n(o,{href:"http://wangzk.win"},{default:d(()=>[...s[7]||(s[7]=[a("willcoderwang",-1)])]),_:1}),s[11]||(s[11]=a(" 校对：",-1)),n(o,{href:"https://github.com/jasminepeng"},{default:d(()=>[...s[8]||(s[8]=[a("jasminepeng",-1)])]),_:1})]),e("p",null,[s[14]||(s[14]=a("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:d(()=>[...s[13]||(s[13]=[a("Linux中国",-1)])]),_:1}),s[16]||(s[16]=a(" 荣誉推出",-1))])])}const _=p(m,[["render",u]]);export{A as __pageData,_ as default};
